POWER_PAGE_SOURCE = 'using System;\nusing System.Drawing;\nusing KMC.Engine.Analysis;\nusing KMC.Engine.Electrical;\nusing KMC.MissionControl.Controls;\nusing KMC.MissionControl.Engineering;\nusing KMC.MissionControl.Models;\nusing KMC.MissionControl.Rendering;\nusing KMC.MissionControl.Rendering.Power;\nusing System.Windows.Forms;\n\nnamespace KMC.MissionControl.Pages\n{\n    /// <summary>\n    /// Build 14.11.2 EECOM POWER redesign foundation.\n    ///\n    /// POWER 1/2 is now a performance-first top-to-bottom one-line schematic.\n    /// The legacy POWER renderer is intentionally not called. Page 2/2 is\n    /// visually reserved for the later detail/analysis page.\n    /// </summary>\n    public sealed class PowerPage :\n        IMissionPage,\n        IMissionPageCanvasProvider,\n        IMessageFilter\n    {\n        // POWER RESERVED NAV RAIL\n        private const int NavRailWidth = 220;\n        private const int NavRailGap = 18;\n\n        private const int WmLeftButtonDown =\n            0x0201;\n\n        private int _subpage = 1;\n\n        private Rectangle _oneLineTab;\n        private Rectangle _breakerTab;\n        private Rectangle _detailTab;\n\n        private int _sourceInventoryPage;\n        private int _sourceInventoryPageCount = 1;\n        private Rectangle _sourcePreviousButton;\n        private Rectangle _sourceNextButton;\n\n        public PowerPage()\n        {\n            /*\n             * Build 14.13.4:\n             * MainForm constructs the POWER page during navigation setup even\n             * when another page is selected. Starting the lease sender here\n             * therefore does not make real EC loading dependent on POWER being\n             * visible.\n             */\n            ElectricalLoadLeaseSender.EnsureStarted();\n\n            /*\n             * Build 14.14.1:\n             * Match PROP\'s proven internal-page navigation mechanism.\n             */\n            Application.AddMessageFilter(\n                this);\n        }\n\n        public string Name\n        {\n            get { return "POWER"; }\n        }\n\n        public Size PreferredVirtualCanvasSize\n        {\n            get\n            {\n                /*\n                 * Keep a bounded high-resolution logical canvas. 2400 x 900 has\n                 * nearly the same pixel count as 1920 x 1080, but matches\n                 * KMC\'s wide CRT much better so POWER fills the display\n                 * without returning to the oversized responsive bitmap.\n                 */\n                return new Size(\n                    3000,\n                    1250);\n            }\n        }\n\n        public MissionPageContentProfile ContentProfile\n        {\n            get\n            {\n                return MissionPageContentProfile.DenseEngineering;\n            }\n        }\n\n        public bool PreFilterMessage(\n            ref Message message)\n        {\n            if (message.Msg !=\n                WmLeftButtonDown)\n            {\n                return false;\n            }\n\n            MissionDisplay display =\n                Control.FromHandle(\n                    message.HWnd) as\n                MissionDisplay;\n\n            if (display == null ||\n                !string.Equals(\n                    display.ScreenTitle,\n                    "POWER DATA",\n                    StringComparison.OrdinalIgnoreCase))\n            {\n                return false;\n            }\n\n            long packed =\n                message.LParam.ToInt64();\n\n            Point clientPoint =\n                new Point(\n                    (short)(packed & 0xFFFF),\n                    (short)((packed >> 16) & 0xFFFF));\n\n            PointF virtualPoint;\n\n            if (!display.TryClientToVirtual(\n                    clientPoint,\n                    out virtualPoint))\n            {\n                return false;\n            }\n\n            Point point =\n                Point.Round(\n                    virtualPoint);\n\n            int previous =\n                _subpage;\n\n            if (_oneLineTab.Contains(\n                    point))\n            {\n                _subpage = 1;\n            }\n            else if (_breakerTab.Contains(\n                         point))\n            {\n                _subpage = 2;\n            }\n            else if (_detailTab.Contains(\n                         point))\n            {\n                _subpage = 3;\n            }\n            else if (_subpage == 3 &&\n                     _sourcePreviousButton.Contains(\n                         point) &&\n                     _sourceInventoryPage > 0)\n            {\n                _sourceInventoryPage--;\n                display.RequestRender();\n                return false;\n            }\n            else if (_subpage == 3 &&\n                     _sourceNextButton.Contains(\n                         point) &&\n                     _sourceInventoryPage <\n                         _sourceInventoryPageCount - 1)\n            {\n                _sourceInventoryPage++;\n                display.RequestRender();\n                return false;\n            }\n            else\n            {\n                return false;\n            }\n\n            if (previous !=\n                _subpage)\n            {\n                display.RequestRender();\n            }\n\n            return false;\n        }\n\n        public void Draw(\n            MissionRenderContext context,\n            MissionTelemetry telemetry)\n        {\n            if (context == null)\n            {\n                throw new ArgumentNullException(nameof(context));\n            }\n\n            AnalysisPipelineResult engineering;\n\n            EngineeringSnapshotStore.TryGetLatest(\n                out engineering);\n\n            Rectangle pageBounds =\n                new Rectangle(\n                    context.ContentBounds.Left,\n                    context.ContentBounds.Top,\n                    Math.Max(\n                        1,\n                        context.ContentBounds.Width -\n                        NavRailWidth -\n                        NavRailGap),\n                    context.ContentBounds.Height);\n\n            MissionRenderContext pageContext =\n                new MissionRenderContext(\n                    context.Graphics,\n                    pageBounds,\n                    context.LargeFont,\n                    context.SmallFont,\n                    context.PhosphorColor,\n                    context.DimPhosphorColor,\n                    context.VirtualCanvasSize);\n\n            if (_subpage == 2)\n            {\n                PowerBreakerPanelRenderer.Draw(\n                    pageContext,\n                    engineering);\n\n                DrawDistributionEventHeader(\n                    pageContext,\n                    engineering);\n            }\n            else if (_subpage == 3)\n            {\n                /*\n                 * Build 14.14.2C:\n                 * Render POWER 2/2 once using the consolidated two-column\n                 * layout. The previous base-renderer + overlay stack is no\n                 * longer called, eliminating hidden duplicate drawing work.\n                 */\n                int effectivePage;\n\n                PowerDetailConsolidatedRenderer.Draw(\n                    pageContext,\n                    engineering,\n                    _sourceInventoryPage,\n                    out _sourcePreviousButton,\n                    out _sourceNextButton,\n                    out _sourceInventoryPageCount,\n                    out effectivePage);\n\n                _sourceInventoryPage =\n                    effectivePage;\n\n                /*\n                 * Build 14.14.3:\n                 * Compact latest A/B/ESS transition evidence in unused header\n                 * space. This does not alter the consolidated panel geometry.\n                 */\n                DrawDistributionEventHeader(\n                    pageContext,\n                    engineering);\n            }\n            else\n            {\n                PowerSchematicRenderer.Draw(\n                    pageContext,\n                    telemetry,\n                    engineering);\n            }\n\n            DrawSubpageTabs(\n                context);\n        }\n\n        private static void DrawDistributionEventHeader(\n            MissionRenderContext context,\n            AnalysisPipelineResult engineering)\n        {\n            if (context == null)\n            {\n                return;\n            }\n\n            Rectangle content =\n                context.ContentBounds;\n\n            Rectangle box =\n                new Rectangle(\n                    content.Left + 720,\n                    content.Top + 24,\n                    Math.Max(\n                        0,\n                        content.Width - 1130),\n                    32);\n\n            if (box.Width <= 0)\n            {\n                return;\n            }\n\n            ElectricalDistributionEventHistoryModel history =\n                engineering != null &&\n                engineering.Snapshot != null &&\n                engineering.Snapshot.Power != null\n                    ? engineering.Snapshot.Power.DistributionEvents\n                    : null;\n\n            ElectricalDistributionEventRecord latest =\n                history != null\n                    ? history.Latest\n                    : null;\n\n            string text;\n            Color color;\n\n            if (latest == null)\n            {\n                text =\n                    "DIST EVT 00 / BASELINE";\n\n                color =\n                    context.DimPhosphorColor;\n            }\n            else\n            {\n                text =\n                    "DIST EVT " +\n                    history.Count.ToString("00") +\n                    "  " +\n                    latest.TimestampUtc.ToString("HH:mm:ss") +\n                    "Z  " +\n                    (latest.Code ?? "---");\n\n                if (!string.IsNullOrWhiteSpace(\n                        latest.Message))\n                {\n                    text +=\n                        "  [" +\n                        latest.Message +\n                        "]";\n                }\n\n                color =\n                    DistributionEventColor(\n                        latest.Severity,\n                        context);\n            }\n\n            TextRenderer.DrawText(\n                context.Graphics,\n                text.ToUpperInvariant(),\n                context.SmallFont,\n                box,\n                color,\n                TextFormatFlags.Right |\n                TextFormatFlags.VerticalCenter |\n                TextFormatFlags.NoPadding |\n                TextFormatFlags.EndEllipsis);\n        }\n\n        private static Color DistributionEventColor(\n            ElectricalEventSeverity severity,\n            MissionRenderContext context)\n        {\n            switch (severity)\n            {\n                case ElectricalEventSeverity.Info:\n                    return Color.FromArgb(112, 202, 154);\n\n                case ElectricalEventSeverity.Advisory:\n                    return Color.FromArgb(232, 188, 84);\n\n                case ElectricalEventSeverity.Warning:\n                    return Color.FromArgb(236, 142, 66);\n\n                case ElectricalEventSeverity.Critical:\n                    return Color.FromArgb(236, 92, 76);\n\n                default:\n                    return context.DimPhosphorColor;\n            }\n        }\n\n        private void DrawSubpageTabs(\n            MissionRenderContext context)\n        {\n            Rectangle content =\n                context.ContentBounds;\n\n            // VERTICAL POWER SUBPAGE NAV\n            // POWER RESERVED NAV RAIL\n            const int gap = 8;\n            const int tabWidth = 180;\n            const int tabHeight = 36;\n\n            int x =\n                content.Right -\n                NavRailWidth +\n                (NavRailWidth - tabWidth) / 2;\n\n            int y =\n                content.Top + 54;\n\n            _oneLineTab =\n                new Rectangle(\n                    x,\n                    y,\n                    tabWidth,\n                    tabHeight);\n\n            _breakerTab =\n                new Rectangle(\n                    x,\n                    _oneLineTab.Bottom + gap,\n                    tabWidth,\n                    tabHeight);\n\n            _detailTab =\n                new Rectangle(\n                    x,\n                    _breakerTab.Bottom + gap,\n                    tabWidth,\n                    tabHeight);\n\n            DrawTab(\n                context,\n                _oneLineTab,\n                "1/3 ONE-LINE",\n                _subpage == 1);\n\n            DrawTab(\n                context,\n                _breakerTab,\n                "2/3 BREAKERS",\n                _subpage == 2);\n\n            DrawTab(\n                context,\n                _detailTab,\n                "3/3 DETAIL",\n                _subpage == 3);\n        }\n\n        private static void DrawTab(\n            MissionRenderContext context,\n            Rectangle bounds,\n            string text,\n            bool active)\n        {\n            Color color =\n                active\n                    ? context.PhosphorColor\n                    : context.DimPhosphorColor;\n\n            using (Pen border =\n                new Pen(\n                    Color.FromArgb(\n                        active\n                            ? 190\n                            : 105,\n                        color),\n                    active\n                        ? 1.6f\n                        : 1.0f))\n            {\n                context.Graphics.DrawRectangle(\n                    border,\n                    bounds);\n            }\n\n            TextRenderer.DrawText(\n                context.Graphics,\n                text,\n                context.SmallFont,\n                bounds,\n                color,\n                TextFormatFlags.HorizontalCenter |\n                TextFormatFlags.VerticalCenter |\n                TextFormatFlags.NoPadding |\n                TextFormatFlags.EndEllipsis);\n        }\n    }\n}\n'
RENDERER_SOURCE = 'using System;\nusing System.Drawing;\nusing System.Windows.Forms;\nusing KMC.Engine.Analysis;\nusing KMC.Engine.SpacecraftSystems;\nusing KMC.MissionControl.Rendering;\n\nnamespace KMC.MissionControl.Rendering.Power\n{\n    /// <summary>\n    /// KMC 14.21.8 read-only breaker panel.\n    ///\n    /// This renderer consumes the live Engine-owned synthetic electrical\n    /// distribution directly. It does not maintain a second breaker state and\n    /// does not issue breaker commands.\n    /// </summary>\n    internal static class PowerBreakerPanelRenderer\n    {\n        private static readonly Color Healthy =\n            Color.FromArgb(112, 202, 154);\n\n        private static readonly Color Advisory =\n            Color.FromArgb(232, 188, 84);\n\n        private static readonly Color Critical =\n            Color.FromArgb(236, 92, 76);\n\n        private static readonly Color PanelFill =\n            Color.FromArgb(255, 7, 18, 20);\n\n        private static readonly FeedDefinition[] MainAFeeds =\n        {\n            new FeedDefinition("GEN A", "CONT_GEN_A"),\n            new FeedDefinition("BAT A", "CONT_BAT_A")\n        };\n\n        private static readonly FeedDefinition[] EssentialFeeds =\n        {\n            new FeedDefinition("ESS A", "CONT_ESS_A"),\n            new FeedDefinition("ESS B", "CONT_ESS_B")\n        };\n\n        private static readonly FeedDefinition[] MainBFeeds =\n        {\n            new FeedDefinition("GEN B", "CONT_GEN_B"),\n            new FeedDefinition("BAT B", "CONT_BAT_B")\n        };\n\n        private static readonly BreakerDefinition[] MainA =\n        {\n            new BreakerDefinition("GUIDANCE A", "BRK_GUID_A"),\n            new BreakerDefinition("COMM A", "BRK_COMM_A"),\n            new BreakerDefinition("PROP FEED PUMP A", "BRK_PUMP_A"),\n            new BreakerDefinition("CABIN FAN A", "BRK_CABIN_FAN_A"),\n            new BreakerDefinition("THERMAL HEATER A", "BRK_THERMAL_HEATER_A")\n        };\n\n        private static readonly BreakerDefinition[] Essential =\n        {\n            new BreakerDefinition("FLIGHT COMPUTER", "BRK_FLIGHT_COMPUTER"),\n            new BreakerDefinition("INSTRUMENTATION", "BRK_INSTRUMENTATION_ESS"),\n            new BreakerDefinition("FLIGHT CONTROL", "BRK_FLIGHT_CONTROL"),\n            new BreakerDefinition("REACTION WHEEL", "BRK_REACTION_WHEEL"),\n            new BreakerDefinition("ENGINE CONTROL", "BRK_ENGINE_CONTROL"),\n            new BreakerDefinition("STAGING CONTROL", "BRK_STAGING_CONTROL"),\n            new BreakerDefinition("BRAKE CONTROL", "BRK_BRAKE_CONTROL"),\n            new BreakerDefinition("GEAR CONTROL", "BRK_GEAR_CONTROL"),\n            new BreakerDefinition("LIGHTING ESS", "BRK_LIGHTING_ESS"),\n            new BreakerDefinition("RCS CONTROL", "BRK_RCS_CONTROL")\n        };\n\n        private static readonly BreakerDefinition[] MainB =\n        {\n            new BreakerDefinition("GUIDANCE B", "BRK_GUID_B"),\n            new BreakerDefinition("COMM B", "BRK_COMM_B"),\n            new BreakerDefinition("PROP FEED PUMP B", "BRK_PUMP_B"),\n            new BreakerDefinition("CABIN FAN B", "BRK_CABIN_FAN_B"),\n            new BreakerDefinition("THERMAL HEATER B", "BRK_THERMAL_HEATER_B")\n        };\n\n        public static void Draw(\n            MissionRenderContext context,\n            AnalysisPipelineResult engineering)\n        {\n            if (context == null)\n            {\n                return;\n            }\n\n            Graphics graphics =\n                context.Graphics;\n\n            Rectangle content =\n                context.ContentBounds;\n\n            Rectangle area =\n                new Rectangle(\n                    content.Left + 14,\n                    content.Top + 112,\n                    Math.Max(0, content.Width - 28),\n                    Math.Max(0, content.Height - 128));\n\n            using (SolidBrush clear =\n                new SolidBrush(\n                    Color.FromArgb(255, 4, 15, 18)))\n            {\n                graphics.FillRectangle(\n                    clear,\n                    area);\n            }\n\n            DrawText(\n                context,\n                new Rectangle(\n                    area.Left + 10,\n                    area.Top - 42,\n                    area.Width - 20,\n                    34),\n                "ELECTRICAL SYSTEMS / BREAKERS",\n                context.DimPhosphorColor,\n                TextFormatFlags.Left |\n                TextFormatFlags.VerticalCenter |\n                TextFormatFlags.NoPadding |\n                TextFormatFlags.EndEllipsis);\n\n            SyntheticElectricalDistributionModel distribution =\n                engineering != null &&\n                engineering.Snapshot != null &&\n                engineering.Snapshot.SpacecraftSystems != null\n                    ? engineering.Snapshot.SpacecraftSystems.ElectricalDistribution\n                    : null;\n\n            if (distribution == null)\n            {\n                DrawCentered(\n                    context,\n                    area,\n                    "ELECTRICAL BREAKER DATA WAITING");\n                return;\n            }\n\n            const int gap = 18;\n            int usableWidth =\n                Math.Max(\n                    0,\n                    area.Width -\n                    gap * 2);\n\n            int columnWidth =\n                usableWidth / 3;\n\n            Rectangle left =\n                new Rectangle(\n                    area.Left,\n                    area.Top,\n                    columnWidth,\n                    area.Height);\n\n            Rectangle middle =\n                new Rectangle(\n                    left.Right + gap,\n                    area.Top,\n                    columnWidth,\n                    area.Height);\n\n            Rectangle right =\n                new Rectangle(\n                    middle.Right + gap,\n                    area.Top,\n                    Math.Max(\n                        0,\n                        area.Right -\n                        middle.Right -\n                        gap),\n                    area.Height);\n\n            DrawBusPanel(\n                context,\n                left,\n                "MAIN BUS A",\n                MainAFeeds,\n                MainA,\n                distribution);\n\n            DrawBusPanel(\n                context,\n                middle,\n                "ESSENTIAL BUS",\n                EssentialFeeds,\n                Essential,\n                distribution);\n\n            DrawBusPanel(\n                context,\n                right,\n                "MAIN BUS B",\n                MainBFeeds,\n                MainB,\n                distribution);\n        }\n\n        private static void DrawBusPanel(\n            MissionRenderContext context,\n            Rectangle panel,\n            string title,\n            FeedDefinition[] feeds,\n            BreakerDefinition[] definitions,\n            SyntheticElectricalDistributionModel distribution)\n        {\n            if (panel.Width <= 0 ||\n                panel.Height <= 0)\n            {\n                return;\n            }\n\n            using (SolidBrush fill =\n                new SolidBrush(\n                    PanelFill))\n            {\n                context.Graphics.FillRectangle(\n                    fill,\n                    panel);\n            }\n\n            using (Pen border =\n                new Pen(\n                    Color.FromArgb(\n                        105,\n                        context.DimPhosphorColor),\n                    1.0f))\n            {\n                context.Graphics.DrawRectangle(\n                    border,\n                    panel);\n            }\n\n            Rectangle titleBox =\n                new Rectangle(\n                    panel.Left + 10,\n                    panel.Top + 8,\n                    Math.Max(0, panel.Width - 20),\n                    32);\n\n            DrawText(\n                context,\n                titleBox,\n                title,\n                context.PhosphorColor,\n                TextFormatFlags.HorizontalCenter |\n                TextFormatFlags.VerticalCenter |\n                TextFormatFlags.NoPadding |\n                TextFormatFlags.EndEllipsis);\n\n            int feedTop =\n                titleBox.Bottom + 4;\n\n            int bodyLeft =\n                panel.Left + 12;\n\n            int bodyWidth =\n                Math.Max(\n                    0,\n                    panel.Width - 24);\n\n            DrawFeedStrip(\n                context,\n                new Rectangle(\n                    bodyLeft,\n                    feedTop,\n                    bodyWidth,\n                    34),\n                feeds,\n                distribution);\n\n            int headerTop =\n                feedTop + 42;\n\n            ColumnLayout columns =\n                ColumnLayout.Create(\n                    bodyLeft,\n                    bodyWidth);\n\n            DrawColumnHeader(\n                context,\n                headerTop,\n                columns);\n\n            int rowsTop =\n                headerTop + 30;\n\n            int availableHeight =\n                Math.Max(\n                    0,\n                    panel.Bottom -\n                    rowsTop -\n                    10);\n\n            int rowHeight =\n                Math.Max(\n                    36,\n                    Math.Min(\n                        72,\n                        definitions.Length > 0\n                            ? availableHeight /\n                              definitions.Length\n                            : availableHeight));\n\n            for (int index = 0;\n                 index < definitions.Length;\n                 index++)\n            {\n                int top =\n                    rowsTop +\n                    index * rowHeight;\n\n                if (top >= panel.Bottom - 8)\n                {\n                    break;\n                }\n\n                Rectangle row =\n                    new Rectangle(\n                        bodyLeft,\n                        top,\n                        bodyWidth,\n                        Math.Min(\n                            rowHeight,\n                            panel.Bottom -\n                            top -\n                            8));\n\n                DrawBreakerRow(\n                    context,\n                    row,\n                    columns,\n                    definitions[index],\n                    distribution);\n            }\n        }\n\n        private static void DrawFeedStrip(\n            MissionRenderContext context,\n            Rectangle area,\n            FeedDefinition[] feeds,\n            SyntheticElectricalDistributionModel distribution)\n        {\n            if (feeds == null ||\n                feeds.Length == 0 ||\n                area.Width <= 0 ||\n                area.Height <= 0)\n            {\n                return;\n            }\n\n            int halfWidth =\n                area.Width / 2;\n\n            for (int index = 0;\n                 index < feeds.Length &&\n                 index < 2;\n                 index++)\n            {\n                FeedDefinition definition =\n                    feeds[index];\n\n                Rectangle item =\n                    new Rectangle(\n                        area.Left + index * halfWidth,\n                        area.Top,\n                        index == 1\n                            ? area.Right - (area.Left + halfWidth)\n                            : halfWidth,\n                        area.Height);\n\n                SyntheticElectricalSwitch feed =\n                    distribution != null\n                        ? distribution.FindSwitch(\n                            definition.SwitchId)\n                        : null;\n\n                string command =\n                    feed != null\n                        ? feed.CommandedClosed\n                            ? "CL"\n                            : "OP"\n                        : "--";\n\n                string indication =\n                    feed != null\n                        ? feed.IndicatedClosed\n                            ? "CL"\n                            : "OP"\n                        : "--";\n\n                Color color =\n                    feed == null\n                        ? context.DimPhosphorColor\n                        : feed.CommandedClosed !=\n                          feed.IndicatedClosed\n                            ? Critical\n                            : feed.IndicatedClosed\n                                ? Healthy\n                                : Advisory;\n\n                // COMPACT POWER FEED STRIP\n                // Keep NAME / CMD / IND grouped together.\n                int nameWidth =\n                    item.Width * 22 / 100;\n\n                int commandWidth =\n                    item.Width * 27 / 100;\n\n                int indicationWidth =\n                    item.Width * 27 / 100;\n\n                // RIGHT-ALIGN SECOND FEED GROUP\n                int groupWidth =\n                    nameWidth +\n                    commandWidth +\n                    indicationWidth;\n\n                int groupLeft =\n                    index == 1\n                        ? item.Right -\n                          groupWidth\n                        : item.Left;\n\n                DrawText(\n                    context,\n                    new Rectangle(\n                        groupLeft,\n                        item.Top,\n                        nameWidth,\n                        item.Height),\n                    definition.Name,\n                    color,\n                    TextFormatFlags.Left |\n                    TextFormatFlags.VerticalCenter |\n                    TextFormatFlags.NoPadding |\n                    TextFormatFlags.EndEllipsis);\n\n                DrawText(\n                    context,\n                    new Rectangle(\n                        groupLeft + nameWidth,\n                        item.Top,\n                        commandWidth,\n                        item.Height),\n                    "CMD " + command,\n                    color,\n                    CenterFlags());\n\n                DrawText(\n                    context,\n                    new Rectangle(\n                        groupLeft + nameWidth + commandWidth,\n                        item.Top,\n                        indicationWidth,\n                        item.Height),\n                    "IND " + indication,\n                    color,\n                    CenterFlags());\n            }\n\n            using (Pen divider =\n                new Pen(\n                    Color.FromArgb(\n                        72,\n                        context.DimPhosphorColor),\n                    1.0f))\n            {\n                context.Graphics.DrawLine(\n                    divider,\n                    area.Left,\n                    area.Bottom + 2,\n                    area.Right,\n                    area.Bottom + 2);\n            }\n        }\n\n        private static void DrawColumnHeader(\n            MissionRenderContext context,\n            int top,\n            ColumnLayout columns)\n        {\n            DrawText(\n                context,\n                new Rectangle(\n                    columns.CommandLeft,\n                    top,\n                    columns.CommandWidth,\n                    28),\n                "CMD",\n                context.DimPhosphorColor,\n                CenterFlags());\n\n            DrawText(\n                context,\n                new Rectangle(\n                    columns.IndicationLeft,\n                    top,\n                    columns.IndicationWidth,\n                    28),\n                "IND",\n                context.DimPhosphorColor,\n                CenterFlags());\n\n            DrawText(\n                context,\n                new Rectangle(\n                    columns.StateLeft,\n                    top,\n                    columns.StateWidth,\n                    28),\n                "STATE",\n                context.DimPhosphorColor,\n                CenterFlags());\n\n            DrawText(\n                context,\n                new Rectangle(\n                    columns.LoadLeft,\n                    top,\n                    columns.LoadWidth,\n                    28),\n                "LOAD",\n                context.DimPhosphorColor,\n                CenterFlags());\n        }\n\n        private static void DrawBreakerRow(\n            MissionRenderContext context,\n            Rectangle row,\n            ColumnLayout columns,\n            BreakerDefinition definition,\n            SyntheticElectricalDistributionModel distribution)\n        {\n            SyntheticElectricalSwitch breaker =\n                distribution.FindSwitch(\n                    definition.BreakerId);\n\n            SyntheticElectricalLoad load =\n                FindLoad(\n                    distribution,\n                    definition.BreakerId);\n\n            bool known =\n                breaker != null &&\n                load != null;\n\n            string command =\n                known\n                    ? breaker.CommandedClosed\n                        ? "CLOSED"\n                        : "OPEN"\n                    : "--";\n\n            string indication =\n                known\n                    ? breaker.IndicatedClosed\n                        ? "CLOSED"\n                        : "OPEN"\n                    : "--";\n\n            string state =\n                known\n                    ? breaker.Conducting\n                        ? "POWERED"\n                        : "UNPOWERED"\n                    : "UNKNOWN";\n\n            double displayedAmps =\n                known &&\n                breaker.Conducting\n                    ? Math.Max(\n                        0.0,\n                        load.DemandAmps)\n                    : 0.0;\n\n            string loadText =\n                known\n                    ? displayedAmps.ToString("0.0") + "A"\n                    : "--";\n\n            Color stateColor =\n                !known\n                    ? context.DimPhosphorColor\n                    : breaker.CommandedClosed !=\n                      breaker.IndicatedClosed\n                        ? Critical\n                        : breaker.Conducting\n                            ? Healthy\n                            : Advisory;\n\n            DrawText(\n                context,\n                new Rectangle(\n                    columns.NameLeft + 4,\n                    row.Top,\n                    Math.Max(\n                        0,\n                        columns.NameWidth - 8),\n                    row.Height),\n                definition.Name,\n                context.PhosphorColor,\n                TextFormatFlags.Left |\n                TextFormatFlags.VerticalCenter |\n                TextFormatFlags.NoPadding |\n                TextFormatFlags.EndEllipsis);\n\n            DrawValue(\n                context,\n                row,\n                columns.CommandLeft,\n                columns.CommandWidth,\n                command,\n                stateColor);\n\n            DrawValue(\n                context,\n                row,\n                columns.IndicationLeft,\n                columns.IndicationWidth,\n                indication,\n                stateColor);\n\n            DrawValue(\n                context,\n                row,\n                columns.StateLeft,\n                columns.StateWidth,\n                state,\n                stateColor);\n\n            DrawValue(\n                context,\n                row,\n                columns.LoadLeft,\n                columns.LoadWidth,\n                loadText,\n                stateColor);\n\n            using (Pen divider =\n                new Pen(\n                    Color.FromArgb(\n                        48,\n                        context.DimPhosphorColor),\n                    1.0f))\n            {\n                context.Graphics.DrawLine(\n                    divider,\n                    row.Left,\n                    row.Bottom - 1,\n                    row.Right,\n                    row.Bottom - 1);\n            }\n        }\n\n        private static SyntheticElectricalLoad FindLoad(\n            SyntheticElectricalDistributionModel distribution,\n            string breakerId)\n        {\n            if (distribution == null ||\n                string.IsNullOrWhiteSpace(\n                    breakerId))\n            {\n                return null;\n            }\n\n            for (int index = 0;\n                 index < distribution.Loads.Count;\n                 index++)\n            {\n                SyntheticElectricalLoad load =\n                    distribution.Loads[index];\n\n                if (load != null &&\n                    string.Equals(\n                        load.BreakerId,\n                        breakerId,\n                        StringComparison.Ordinal))\n                {\n                    return load;\n                }\n            }\n\n            return null;\n        }\n\n        private static void DrawValue(\n            MissionRenderContext context,\n            Rectangle row,\n            int left,\n            int width,\n            string value,\n            Color color)\n        {\n            DrawText(\n                context,\n                new Rectangle(\n                    left,\n                    row.Top,\n                    width,\n                    row.Height),\n                value,\n                color,\n                CenterFlags());\n        }\n\n        private static TextFormatFlags CenterFlags()\n        {\n            return\n                TextFormatFlags.HorizontalCenter |\n                TextFormatFlags.VerticalCenter |\n                TextFormatFlags.NoPadding |\n                TextFormatFlags.EndEllipsis;\n        }\n\n        private static void DrawCentered(\n            MissionRenderContext context,\n            Rectangle area,\n            string text)\n        {\n            DrawText(\n                context,\n                area,\n                text,\n                context.DimPhosphorColor,\n                TextFormatFlags.HorizontalCenter |\n                TextFormatFlags.VerticalCenter |\n                TextFormatFlags.NoPadding |\n                TextFormatFlags.EndEllipsis);\n        }\n\n        private static void DrawText(\n            MissionRenderContext context,\n            Rectangle bounds,\n            string text,\n            Color color,\n            TextFormatFlags flags)\n        {\n            if (bounds.Width <= 0 ||\n                bounds.Height <= 0)\n            {\n                return;\n            }\n\n            TextRenderer.DrawText(\n                context.Graphics,\n                text ?? string.Empty,\n                context.SmallFont,\n                bounds,\n                color,\n                flags);\n        }\n\n        private sealed class FeedDefinition\n        {\n            public FeedDefinition(\n                string name,\n                string switchId)\n            {\n                Name =\n                    name ?? string.Empty;\n\n                SwitchId =\n                    switchId ?? string.Empty;\n            }\n\n            public string Name\n            {\n                get;\n                private set;\n            }\n\n            public string SwitchId\n            {\n                get;\n                private set;\n            }\n        }\n\n        private sealed class BreakerDefinition\n        {\n            public BreakerDefinition(\n                string name,\n                string breakerId)\n            {\n                Name =\n                    name ?? string.Empty;\n\n                BreakerId =\n                    breakerId ?? string.Empty;\n            }\n\n            public string Name\n            {\n                get;\n                private set;\n            }\n\n            public string BreakerId\n            {\n                get;\n                private set;\n            }\n        }\n\n        private sealed class ColumnLayout\n        {\n            public int NameLeft { get; private set; }\n            public int NameWidth { get; private set; }\n            public int CommandLeft { get; private set; }\n            public int CommandWidth { get; private set; }\n            public int IndicationLeft { get; private set; }\n            public int IndicationWidth { get; private set; }\n            public int StateLeft { get; private set; }\n            public int StateWidth { get; private set; }\n            public int LoadLeft { get; private set; }\n            public int LoadWidth { get; private set; }\n\n            public static ColumnLayout Create(\n                int left,\n                int width)\n            {\n                int nameWidth =\n                    width * 42 / 100;\n\n                int commandWidth =\n                    width * 13 / 100;\n\n                int indicationWidth =\n                    width * 13 / 100;\n\n                int stateWidth =\n                    width * 20 / 100;\n\n                int loadWidth =\n                    Math.Max(\n                        0,\n                        width -\n                        nameWidth -\n                        commandWidth -\n                        indicationWidth -\n                        stateWidth);\n\n                ColumnLayout layout =\n                    new ColumnLayout();\n\n                layout.NameLeft =\n                    left;\n                layout.NameWidth =\n                    nameWidth;\n\n                layout.CommandLeft =\n                    layout.NameLeft +\n                    layout.NameWidth;\n                layout.CommandWidth =\n                    commandWidth;\n\n                layout.IndicationLeft =\n                    layout.CommandLeft +\n                    layout.CommandWidth;\n                layout.IndicationWidth =\n                    indicationWidth;\n\n                layout.StateLeft =\n                    layout.IndicationLeft +\n                    layout.IndicationWidth;\n                layout.StateWidth =\n                    stateWidth;\n\n                layout.LoadLeft =\n                    layout.StateLeft +\n                    layout.StateWidth;\n                layout.LoadWidth =\n                    loadWidth;\n\n                return layout;\n            }\n        }\n    }\n}'

def patch_csproj(text):
    needle = r'<Compile Include="Rendering\Power\PowerBreakerPanelRenderer.cs" />'
    if needle in text:
        return text

    anchor = r'<Compile Include="Rendering\Power\PowerDetailConsolidatedRenderer.cs" />'
    if anchor not in text:
        raise RuntimeError("Could not locate POWER renderer project-file anchor.")

    return text.replace(anchor, needle + anchor, 1)

def validate_repo():
    if not POWER_PAGE.exists():
        raise RuntimeError("Run this script from a KMC repository checkout.")
    if not CSPROJ.exists():
        raise RuntimeError("KMC.MissionControl.csproj not found.")

    current = POWER_PAGE.read_text(encoding="utf-8-sig")
    known_base = '"1/2 ONE-LINE"' in current and '"2/2 DETAIL"' in current
    known_final = "POWER RESERVED NAV RAIL" in current and '"2/3 BREAKERS"' in current

    if not known_base and not known_final:
        raise RuntimeError(
            "PowerPage.cs is not the expected frozen 14.21.7 base or final 14.21.8 shape."
        )

def main():
    validate_repo()

    project_before = CSPROJ.read_text(encoding="utf-8-sig")
    project_after = patch_csproj(project_before)

    RENDERER.parent.mkdir(parents=True, exist_ok=True)

    POWER_PAGE.write_text(POWER_PAGE_SOURCE, encoding="utf-8")
    RENDERER.write_text(RENDERER_SOURCE, encoding="utf-8")
    CSPROJ.write_text(project_after, encoding="utf-8")

    print("14.21.8 applied: final POWER breaker status page.")
    print("POWER nav: reserved right-side rail.")
    print("Breakers: 20 live branches with source/feed status.")
    print("KSP Plugin DLL Required? NO")

if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print("ERROR: " + str(exc), file=sys.stderr)
        sys.exit(1)
